import{_ as a,o as i,c as s,a2 as e}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"测试分层与回归保护","description":"以风险和反馈速度决定测试层次，用少量高价值用例保护业务规则与关键用户路径。","frontmatter":{"title":"测试分层与回归保护","description":"以风险和反馈速度决定测试层次，用少量高价值用例保护业务规则与关键用户路径。"},"headers":[],"relativePath":"engineering/testing.md","filePath":"engineering/testing.md","lastUpdated":1786262003000}'),d={name:"engineering/testing.md"};function n(h,t,l,r,p,k){return i(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="测试分层与回归保护" tabindex="-1">测试分层与回归保护 <a class="header-anchor" href="#测试分层与回归保护" aria-label="Permalink to &quot;测试分层与回归保护&quot;">​</a></h1><p>测试的目的不是追求覆盖率数字，而是让团队能放心修改。最值得自动化的，是容易回归、影响大的业务规则和关键用户流程。</p><h2 id="不同层次回答不同问题" tabindex="-1">不同层次回答不同问题 <a class="header-anchor" href="#不同层次回答不同问题" aria-label="Permalink to &quot;不同层次回答不同问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>验证对象</th><th>特点</th></tr></thead><tbody><tr><td>单元测试</td><td>函数、规则、转换逻辑</td><td>反馈快，定位明确</td></tr><tr><td>集成测试</td><td>模块协作、数据库或接口边界</td><td>发现真实组合问题</td></tr><tr><td>端到端测试</td><td>用户关键流程</td><td>贴近真实，但维护成本更高</td></tr></tbody></table><p>不必为每个 UI 像素写端到端测试。把规则放在可独立测试的模块中，用少量流程测试确认页面、接口和权限真正协作即可。</p><h2 id="从失败风险挑选用例" tabindex="-1">从失败风险挑选用例 <a class="header-anchor" href="#从失败风险挑选用例" aria-label="Permalink to &quot;从失败风险挑选用例&quot;">​</a></h2><p>优先覆盖这些场景：</p><ul><li>金额、库存、权限等不能算错或越权的规则。</li><li>曾经出现过的缺陷，避免同样问题再次发生。</li><li>输入边界：空值、极值、重复提交、过期数据。</li><li>失败分支：网络超时、依赖异常、无权限、资源不存在。</li></ul><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">it</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;普通成员不能编辑他人文章&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  expect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">canUpdateArticle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(memberA, articleOfMemberB)).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toBe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>用例名称应描述用户或业务结果，而不是内部方法调用。失败报告才能直接告诉读者“什么行为被破坏了”。</p><h2 id="让测试可重复" tabindex="-1">让测试可重复 <a class="header-anchor" href="#让测试可重复" aria-label="Permalink to &quot;让测试可重复&quot;">​</a></h2><p>测试数据需要独立、可预测，并在结束时清理。时间、随机数、网络和第三方依赖应可替换或固定，否则测试会因环境抖动而失去信任。</p><table tabindex="0"><thead><tr><th>不稳定来源</th><th>常用处理</th></tr></thead><tbody><tr><td>当前时间</td><td>注入时钟或固定时间</td></tr><tr><td>外部接口</td><td>使用契约 mock 或测试环境</td></tr><tr><td>随机数据</td><td>固定种子或显式样例</td></tr><tr><td>共享数据库</td><td>每个用例独立准备与回收数据</td></tr></tbody></table><h2 id="测试不是发布后的借口" tabindex="-1">测试不是发布后的借口 <a class="header-anchor" href="#测试不是发布后的借口" aria-label="Permalink to &quot;测试不是发布后的借口&quot;">​</a></h2><p>自动化通过不代表没有风险。上线前仍需确认配置、权限、数据迁移和监控；上线后把真实故障转化为下一条测试或约束，测试集才会持续变得有价值。</p>`,15)])])}const E=a(d,[["render",n]]);export{c as __pageData,E as default};
